import { DateInputForm } from '@/components/forms/DateInputForm';
import SmallImgInputForm from '@/components/forms/SmallImgInputForm';
import TextInputForm from '@/components/forms/TextInputForm';

interface Props {
    image: string | null | undefined;
}

export default function PersonalInfo({ image }: Props) {
    return (
        <div className="mb-6 grid grid-cols-1 gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(200px,210px)]">
            <div className="flex flex-col gap-4">
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                    <TextInputForm name="name" label="اسم الموظف" placeholder="ادخل اسم الموظف" />
                    <TextInputForm name="address" label="العنوان" placeholder="ادخل العنوان" />
                </div>

                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                    <TextInputForm name="id_number" label="رقم الهوية" placeholder="ادخل رقم الهوية" />
                    <DateInputForm name="birth_date" label="تاريخ الميلاد" placeholder="ادخل تاريخ الميلاد" />
                </div>

                <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
                    <TextInputForm
                        name="phone_number"
                        label="رقم الهاتف"
                        placeholder="ادخل رقم الهاتف"
                        type="tel"
                        className="[&>input]:text-end [&>input]:placeholder:text-end"
                    />
                    <TextInputForm
                        name="email"
                        label="البريد الالكتروني"
                        placeholder="ادخل البريد الالكتروني"
                    />
                    <TextInputForm
                        name="password"
                        label="الرقم السري"
                        placeholder="ادخل الرقم السري للموظف"
                        type="password"
                    />
                </div>
            </div>

            <div className="lg:max-w-[200px]">
                {image ? (
                    <SmallImgInputForm
                        name="personal_image"
                        maxSize={10 * 1024 * 1024}
                        multiple={false}
                        label="الصورة الشخصية"
                        editImages={image}
                    />
                ) : (
                    <SmallImgInputForm
                        name="personal_image"
                        maxSize={10 * 1024 * 1024}
                        multiple={false}
                        label="الصورة الشخصية"
                    />
                )}
                <p className="mt-2 text-center text-xs leading-relaxed text-[#90868C]">
                    الملفات المسموح بها: jpg, png
                    <span className="mx-1">·</span>
                    أقصى حجم: 10MB
                </p>
            </div>
        </div>
    );
}
